const fs = require('fs');
const rutas = $('Rutas').first().json;
// La configuración se lee del disco en cada vuelta: un git pull de config/ vale desde la vuelta siguiente.
const leer = archivo => JSON.parse(fs.readFileSync(rutas.carpetaRepo + '/' + archivo, 'utf8'));
const feeds = leer('config/feeds.json').feeds.filter(f => f.url);
const portales = leer('config/portales.json').portales;
const reglas = leer('config/reglas.json');
const firmas = leer('config/firmas.json').firmas;
// src/capa4.js queda en memoria: un git pull del código vale después de reiniciar n8n.
const capa4 = require(rutas.carpetaRepo + '/src/capa4.js');
// Los casos de unión de test/casos-ia.json que no son «dudoso», 3 veces cada uno, con la misma configuración que la vuelta.
const casos = leer('test/casos-ia.json');
return capa4.itemsDePrueba(casos, { portales, reglas }).map(i => ({ json: i }));

const fs = require('fs');
const rutas = $('Rutas').first().json;
// La configuración se lee del disco en cada vuelta: un git pull de config/ vale desde la vuelta siguiente.
const leer = archivo => JSON.parse(fs.readFileSync(rutas.carpetaRepo + '/' + archivo, 'utf8'));
const feeds = leer('config/feeds.json').feeds.filter(f => f.url);
const portales = leer('config/portales.json').portales;
const reglas = leer('config/reglas.json');
const firmas = leer('config/firmas.json').firmas;
// src/capa4.js queda en memoria: un git pull del código vale después de reiniciar n8n.
const capa4 = require(rutas.carpetaRepo + '/src/capa4.js');
const casos = leer('test/casos-ia.json');
const items = $('Casos').all().map(i => i.json);
const respuestas = $input.all().map(i => i.json);
// Un ítem por caso ({ caso, titulos, esperado, intentos, pasa }) y al final { resumen: 'pasa' | 'no pasa', casos, aciertos, de }.
// La unión se prende solo con «pasa»: los 3 intentos bien en todos los casos.
return capa4.resultadoPrueba(casos, items, respuestas).map(j => ({ json: j }));
